<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import Modal from 'ant-design-vue/es/modal'
import message from 'ant-design-vue/es/message'
import { Bot, Plus, RefreshCw, Save, ShieldCheck, Trash2, UserPlus, Users } from '@lucide/vue'
import { agentApi, type AgentPayload } from '@/api/agent'
import { workspaceApi } from '@/api/workspace'
import AppShell from '@/components/AppShell.vue'
import PageHeader from '@/components/PageHeader.vue'
import type { AgentDefinition, WorkspaceMember } from '@/types'

const route = useRoute(); const workspaceId = computed(() => String(route.params.workspaceId)); const activeTab = ref('members'); const members = ref<WorkspaceMember[]>([]); const agents = ref<AgentDefinition[]>([]); const loading = ref(false); const memberModal = ref(false); const memberLoading = ref(false); const memberForm = ref({ userId: '', role: 'MEMBER' }); const agentModal = ref(false); const agentLoading = ref(false); const editingAgent = ref<AgentDefinition | null>(null); const agentForm = ref<AgentPayload>({ name: '', agentType: 'researcher', runtime: 'PYTHON', promptVersion: 'v1', systemPrompt: '', enabled: true })
async function load() { loading.value = true; try { [members.value, agents.value] = await Promise.all([workspaceApi.members(workspaceId.value), agentApi.list(workspaceId.value)]) } catch (error) { message.error(error instanceof Error ? error.message : '设置加载失败') } finally { loading.value = false } }
async function addMember() { if (!memberForm.value.userId.trim()) { message.warning('请输入用户 ID'); return }; memberLoading.value = true; try { const member = await workspaceApi.addMember(workspaceId.value, { userId: memberForm.value.userId.trim(), role: memberForm.value.role }); members.value.push(member); memberModal.value = false; memberForm.value = { userId: '', role: 'MEMBER' }; message.success('成员已添加') } catch (error) { message.error(error instanceof Error ? error.message : '添加成员失败') } finally { memberLoading.value = false } }
function removeMember(member: WorkspaceMember) { Modal.confirm({ title: '移除成员', content: `确定从当前工作空间移除 ${member.displayName || member.username}？`, okText: '移除', cancelText: '取消', okButtonProps: { danger: true }, async onOk() { try { await workspaceApi.removeMember(workspaceId.value, member.userId); members.value = members.value.filter((item) => item.userId !== member.userId); message.success('成员已移除') } catch (error) { message.error(error instanceof Error ? error.message : '移除失败') } } }) }
function openCreateAgent() { editingAgent.value = null; agentForm.value = { name: '', agentType: 'researcher', runtime: 'PYTHON', promptVersion: 'v1', systemPrompt: '', enabled: true }; agentModal.value = true }
function openEditAgent(agent: AgentDefinition) { editingAgent.value = agent; agentForm.value = { name: agent.name, agentType: agent.agentType, runtime: agent.runtime, promptVersion: agent.promptVersion, systemPrompt: agent.systemPrompt || '', enabled: agent.enabled }; agentModal.value = true }
async function saveAgent() { if (!agentForm.value.name.trim()) { message.warning('请输入 Agent 名称'); return }; agentLoading.value = true; try { if (editingAgent.value) { const next = await agentApi.update(workspaceId.value, editingAgent.value.id, { name: agentForm.value.name.trim(), promptVersion: agentForm.value.promptVersion, systemPrompt: agentForm.value.systemPrompt }); Object.assign(editingAgent.value, next) } else { agents.value.unshift(await agentApi.create(workspaceId.value, { ...agentForm.value, name: agentForm.value.name.trim() })) }; agentModal.value = false; message.success('Agent 配置已保存') } catch (error) { message.error(error instanceof Error ? error.message : '保存失败') } finally { agentLoading.value = false } }
async function toggleAgent(agent: AgentDefinition, enabled: boolean) { try { const next = await agentApi.enable(workspaceId.value, agent.id, enabled); Object.assign(agent, next) } catch (error) { message.error(error instanceof Error ? error.message : '更新状态失败') } }
onMounted(load)
</script>

<template><AppShell><div class="page-content"><PageHeader eyebrow="WORKSPACE SETTINGS" title="成员与 Agent" description="管理谁可以参与研究，以及任务使用的执行配置。"><a-button :loading="loading" @click="load"><RefreshCw :size="15"/> 刷新</a-button></PageHeader><a-tabs v-model:active-key="activeTab" class="settings-tabs"><a-tab-pane key="members"><template #tab><span class="tab-label"><Users :size="16"/> 成员</span></template><div class="settings-toolbar"><div><h2>工作空间成员</h2><p>成员可以查看任务和知识库，管理员可控制任务。</p></div><a-button type="primary" @click="memberModal = true"><UserPlus :size="15"/> 添加成员</a-button></div><a-table :data-source="members" :loading="loading" row-key="id" :pagination="false"><a-table-column key="member" title="成员"><template #default="{ record }"><div class="member-cell"><div class="avatar">{{ (record.displayName || record.username || '?').slice(0, 1).toUpperCase() }}</div><div><strong>{{ record.displayName || record.username }}</strong><span>{{ record.username }} · {{ record.userId }}</span></div></div></template></a-table-column><a-table-column key="role" title="角色" :width="160"><template #default="{ record }"><a-tag :color="record.role === 'OWNER' ? 'green' : record.role === 'ADMIN' ? 'blue' : 'default'">{{ record.role === 'OWNER' ? '所有者' : record.role === 'ADMIN' ? '管理员' : '成员' }}</a-tag></template></a-table-column><a-table-column key="actions" title="" :width="120"><template #default="{ record }"><a-button v-if="record.role !== 'OWNER'" type="link" danger size="small" @click="removeMember(record)"><Trash2 :size="14"/> 移除</a-button></template></a-table-column><template #emptyText><div class="empty-state"><Users :size="28"/><h3>暂无成员</h3></div></template></a-table></a-tab-pane><a-tab-pane key="agents"><template #tab><span class="tab-label"><Bot :size="16"/> Agent 配置</span></template><div class="settings-toolbar"><div><h2>研究 Agent</h2><p>为不同研究环节维护稳定、可版本化的提示词配置。</p></div><a-button type="primary" @click="openCreateAgent"><Plus :size="15"/> 新建 Agent</a-button></div><div v-if="agents.length" class="agent-grid"><article v-for="agent in agents" :key="agent.id" class="agent-item"><div class="agent-item-heading"><div class="agent-icon"><Bot :size="18"/></div><a-switch :checked="agent.enabled" size="small" @change="toggleAgent(agent, $event as boolean)"/></div><h3>{{ agent.name }}</h3><p>{{ agent.agentType }} · {{ agent.runtime }} · {{ agent.promptVersion }}</p><div class="agent-item-footer"><span><ShieldCheck :size="13"/> {{ agent.enabled ? '可用' : '已停用' }} · v{{ agent.version }}</span><a-button type="link" size="small" @click="openEditAgent(agent)"><Save :size="14"/> 编辑</a-button></div></article></div><div v-else class="empty-state soft-panel"><Bot :size="30"/><h3>还没有 Agent 配置</h3><p>创建一个 Agent 来定义研究执行方式。</p></div></a-tab-pane></a-tabs><Modal v-model:open="memberModal" title="添加成员" :confirm-loading="memberLoading" ok-text="添加" cancel-text="取消" @ok="addMember"><a-form layout="vertical" class="modal-form"><a-form-item label="用户 ID" required><a-input v-model:value="memberForm.userId" placeholder="输入已注册用户 ID"/></a-form-item><a-form-item label="角色"><a-select v-model:value="memberForm.role" style="width: 100%" :options="[{ label: '成员', value: 'MEMBER' }, { label: '管理员', value: 'ADMIN' }]"/></a-form-item></a-form></Modal><Modal v-model:open="agentModal" :title="editingAgent ? '编辑 Agent' : '新建 Agent'" :confirm-loading="agentLoading" ok-text="保存" cancel-text="取消" @ok="saveAgent"><a-form layout="vertical" class="modal-form"><a-form-item label="名称" required><a-input v-model:value="agentForm.name" maxlength="128" placeholder="例如：市场研究员"/></a-form-item><div class="form-split"><a-form-item label="类型"><a-input v-model:value="agentForm.agentType" :disabled="Boolean(editingAgent)"/></a-form-item><a-form-item label="运行时"><a-select v-model:value="agentForm.runtime" :disabled="Boolean(editingAgent)" style="width: 100%" :options="[{ label: 'Python', value: 'PYTHON' }, { label: 'Java', value: 'JAVA' }]"/></a-form-item></div><a-form-item label="提示词版本"><a-input v-model:value="agentForm.promptVersion"/></a-form-item><a-form-item label="系统提示词"><a-textarea v-model:value="agentForm.systemPrompt" :rows="5" placeholder="给这个 Agent 的职责和边界"/></a-form-item><a-form-item v-if="!editingAgent" label="创建后启用"><a-switch v-model:checked="agentForm.enabled"/></a-form-item></a-form></Modal></div></AppShell></template>
